const now = DateTime.now().setZone('Europe/Paris');
// Canaux d'alerte geres dans l'app (onglet Alertes) ; valeurs par defaut si la table est vide.
let canaux = $('Canaux d\'alerte').all().map(i => i.json).filter(c => c && c.nom && c.valeur);
if (!canaux.length) canaux = [
  { nom: 'SSF Alert', valeur: 'https://ssfalert.fr' },
  { nom: 'Numero d urgence europeen', valeur: '112' },
  { nom: 'Speleo Secours Francais', valeur: '0800 121 123' }
];
const consigne = canaux.map(c => c.nom + ' : ' + c.valeur).join(' / ');
const out = [];
for (const item of $input.all()) {
  const s = item.json;
  if (!s.heure_secours || !s.date_sortie) continue;
  let d = DateTime.fromISO(s.date_sortie + 'T' + s.heure_secours, { zone: 'Europe/Paris' });
  if (s.heure_entree && s.heure_secours < s.heure_entree) d = d.plus({ days: 1 });
  if (now > d) {
    s.retard_minutes = Math.round(now.diff(d, 'minutes').minutes);
    s.consigne = consigne;
    out.push({ json: s });
  }
}
return out;

// Ne laisse passer les sorties vers l'email que si l'alerte email est activee
// dans l'onglet Alertes de l'app et qu'il y a au moins un destinataire.
const r = $('Reglages alertes').first().json || {};
if (r.alerte_email === false) return [];
if (!((r.emails_alerte || '').trim())) return [];
return $input.all();

// Croise les sorties en depassement avec les membres qui ont une cle CallMeBot
// (champ "Cle CallMeBot" de la fiche membre, rempli par l'admin dans l'app).
const r = $('Reglages alertes').first().json || {};
if (r.alerte_whatsapp === false) return [];
const sorties = $('Garder les depassees').all().map(i => i.json);
const membres = $input.all().map(i => i.json)
  .filter(m => m.callmebot_key && m.callmebot_key.trim() !== '' && m.telephone);

const out = [];
for (const s of sorties) {
  const texte = 'ALERTE SPELEO : heure de secours depassee de ' + s.retard_minutes + ' min.\n'
    + (s.type_cavite || 'cavite') + ' ' + (s.nom_cavite || '') + (s.departement ? ' (' + s.departement + ')' : '') + '\n'
    + 'Sonnette : ' + (s.sonnette_nom || '?') + ' ' + (s.sonnette_tel || '') + '\n'
    + (s.gps ? 'GPS entree : ' + s.gps + '\n' : '')
    + 'Sans nouvelle : declarer l\'alerte (' + (s.consigne || 'https://ssfalert.fr, 112') + '), dire "accident de speleologie".\n'
    + 'Details et message complet : https://VOTRE-SITE-SONNETTE.example.org';
  for (const m of membres) {
    let dig = (m.telephone || '').replace(/\D/g, '');
    if (dig.indexOf('0') === 0) dig = '33' + dig.slice(1);
    else if (dig.length === 9) dig = '33' + dig;
    out.push({ json: { phone: '+' + dig, apikey: m.callmebot_key.trim(), texte: texte } });
  }
}
return out;
